import { toCents } from './money.mjs';
export function invoiceTotal(lines) {
  if (!Array.isArray(lines)) throw new TypeError('lines');
  let sum = 0;
  for (const line of lines) {
    if (!line || typeof line !== 'object' || !Number.isInteger(line.quantity) || line.quantity < 1 || line.quantity > 1000) throw new TypeError('quantity');
    sum += toCents(line.price) * line.quantity;
  }
  return sum;
}
